package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;

/** Standard reflective RAM invariance stages, with latent intercepts freed only after scalar identification. */
public final class SemInvariance {
    private SemInvariance(){}
    public enum Stage {CONFIGURAL,METRIC,SCALAR,SCALAR_MEANS,STRICT,STRICT_MEANS;
        @Override public String toString(){return switch(this){case CONFIGURAL->"Configural: group-specific parameters";case METRIC->"Metric: equal loadings";case SCALAR->"Scalar: equal loadings and intercepts";case SCALAR_MEANS->"Scalar plus equal latent means";case STRICT->"Strict: equal loadings, intercepts and residual variances";case STRICT_MEANS->"Strict plus equal latent means";};}
        public String referenceCode(){return switch(this){case CONFIGURAL->"MODEL1";case METRIC->"MODEL2";case SCALAR->"MODEL3A";case SCALAR_MEANS->"MODEL3B";case STRICT->"MODEL4A";case STRICT_MEANS->"MODEL4B";};}
    }
    public record Sample(String name,int observations,double[][] covariance,double[] means){public Sample{covariance=Matrices.copy(covariance);means=means.clone();if(name==null||name.isBlank()||observations<3)throw new IllegalArgumentException("Invalid invariance group.");}@Override public double[][] covariance(){return Matrices.copy(covariance);}@Override public double[] means(){return means.clone();}public static Sample fromData(String name,double[][] data,CovarianceSem.Options options){Matrices.width(data,3);var centered=Matrices.standardize(data,false,false);return new Sample(name,data.length,Matrices.covariance(centered.values(),options.likelihood()==CovarianceSem.Likelihood.WISHART),centered.means());}}
    public record Step(Stage stage,MultiGroupSem.Fit fit,String failure,MultiGroupSemComparison.Result previousComparison,String comparisonUnavailable){}
    public record Result(boolean strict,List<Step> steps,List<String> warnings){public Result{steps=List.copyOf(steps);warnings=List.copyOf(warnings);}}
    public static MultiGroupSem.Fit fitStage(SemModel.Prepared template,List<Sample> samples,Stage stage,CovarianceSem.Options options){return MultiGroupSem.fit(specification(template,samples,stage,options,null),options);}
    public static Result sequence(SemModel.Prepared template,List<Sample> supplied,CovarianceSem.Options options,boolean strict,IntConsumer progress){
        if(!options.meanStructure())throw new IllegalArgumentException("Full measurement invariance sequences require the mean structure.");List<Sample> samples=List.copyOf(supplied);validate(template,samples,options);List<Stage> stages=strict?List.of(Stage.CONFIGURAL,Stage.METRIC,Stage.SCALAR,Stage.STRICT,Stage.STRICT_MEANS):List.of(Stage.CONFIGURAL,Stage.METRIC,Stage.SCALAR,Stage.SCALAR_MEANS);List<Step> results=new ArrayList<>();List<String> warnings=new ArrayList<>();MultiGroupSem.Fit previous=null;int index=0;
        for(var stage:stages){Matrices.interrupted();MultiGroupSem.Fit fit=null;String failure=null,unavailable=null;MultiGroupSemComparison.Result comparison=null;try{fit=MultiGroupSem.fit(specification(template,samples,stage,options,previous),options);if(previous!=null)try{comparison=MultiGroupSemComparison.invarianceDifference(fit,previous,"Generated reflective invariance sequence "+stages.get(index-1)+" → "+stage+". Scalar stages allow latent-mean location changes absorbed by the unrestricted observed intercepts; marker scales and covariance structure remain identical.");}catch(IllegalArgumentException problem){unavailable=problem.getMessage();}else if(index>0)unavailable="The previous stage did not produce an estimable fit.";}catch(IllegalArgumentException|ArithmeticException problem){failure=problem.getMessage()==null?problem.getClass().getSimpleName():problem.getMessage();warnings.add(stage+": "+failure);}results.add(new Step(stage,fit,failure,comparison,unavailable));previous=fit;index++;if(progress!=null)progress.accept(index);}
        warnings.add("First group is the latent-mean reference. Metric stages equate loadings; scalar stages also equate observed intercepts and free other groups' latent intercepts; means stages fix all latent intercepts to zero. Strict stages additionally equate observed residual variances. Structural effects, latent variances/covariances and residual covariances remain group-specific unless fixed in the template.");warnings.add("Sequential chi-square tests are unadjusted; inspect convergence, identification, properness and fit-index changes. Scalar nesting is justified at the observed-moment level despite its change of latent-mean location parameterization.");return new Result(strict,results,warnings);
    }
    static List<MultiGroupSem.Group> specification(SemModel.Prepared prepared,List<Sample> samples,Stage stage,CovarianceSem.Options options,MultiGroupSem.Fit previous){
        validate(prepared,samples,options);if(stage!=Stage.CONFIGURAL&&stage!=Stage.METRIC&&!options.meanStructure())throw new IllegalArgumentException("Scalar/strict mean invariance requires enabled mean structure.");var template=prepared.model();int[] observed=template.observed(),factors=prepared.factors();Set<Integer> observedSet=new HashSet<>(),factorSet=new HashSet<>();for(int i:observed)observedSet.add(i);for(int i:factors)factorSet.add(i);int[] markers=markers(template,factors,observed);List<MultiGroupSem.Group> groups=new ArrayList<>();boolean scalar=stage==Stage.SCALAR||stage==Stage.SCALAR_MEANS||stage==Stage.STRICT||stage==Stage.STRICT_MEANS,strict=stage==Stage.STRICT||stage==Stage.STRICT_MEANS,freeMeans=stage==Stage.SCALAR||stage==Stage.STRICT;
        for(int g=0;g<samples.size();g++){
            var sample=samples.get(g);double[][] a=template.directed(),s=template.covariance();double[] m=template.intercepts();List<SemModel.Parameter> parameters=new ArrayList<>();Map<String,String> bindings=new LinkedHashMap<>();var warm=previous!=null&&previous.groups().size()==samples.size()?previous.groups().get(g):null;double[][] warmA=warm==null?null:warm.directed(),warmS=warm==null?null:warm.disturbance();double[] warmM=warm==null?null:warm.fullMeans();
            for(var parameter:template.parameters()){
                var location=parameter.locations().get(0);int row=location.row(),col=location.column(),position=position(observed,row);double start=parameter.start(),scale=parameter.scale();if(warm!=null){start=switch(location.kind()){case DIRECTED->warmA[row][col];case COVARIANCE->warmS[row][col];case INTERCEPT->warmM[row];};}
                if(location.kind()==SemModel.Kind.INTERCEPT&&observedSet.contains(row)){start=scalar?samples.get(0).means[position]:sample.means[position];scale=Math.sqrt(sample.covariance[position][position]);}
                if(location.kind()==SemModel.Kind.COVARIANCE&&row==col&&observedSet.contains(row)){if(warm==null||!(start>0))start=.3*sample.covariance[position][position];scale=sample.covariance[position][position];}
                if(location.kind()==SemModel.Kind.COVARIANCE&&row==col&&factorSet.contains(row)){int f=position(factors,row),marker=position(observed,markers[f]);double loading=template.directed()[markers[f]][row],variance=.7*sample.covariance[marker][marker]/(loading*loading);if(warm==null||!(start>0))start=variance;scale=variance;}
                if(location.kind()==SemModel.Kind.DIRECTED&&observedSet.contains(row)&&factorSet.contains(col)){int f=position(factors,col),marker=position(observed,markers[f]);double latent=.7*sample.covariance[marker][marker]/Math.pow(template.directed()[markers[f]][col],2);if(warm==null)start=sample.covariance[position][marker]/(latent*template.directed()[markers[f]][col]);scale=Math.max(.1,Math.sqrt(sample.covariance[position][position]/latent));}
                if(parameter.lower()!=null)start=Math.max(start,parameter.lower());if(parameter.upper()!=null)start=Math.min(start,parameter.upper());parameters.add(new SemModel.Parameter(parameter.name(),parameter.locations(),start,scale,parameter.lower(),parameter.upper()));boolean loading=location.kind()==SemModel.Kind.DIRECTED&&observedSet.contains(row)&&factorSet.contains(col),intercept=location.kind()==SemModel.Kind.INTERCEPT&&observedSet.contains(row),residual=location.kind()==SemModel.Kind.COVARIANCE&&row==col&&observedSet.contains(row);if(stage!=Stage.CONFIGURAL&&loading||scalar&&intercept||strict&&residual)bindings.put(parameter.name(),"Invariant: "+parameter.name());
            }
            if(options.meanStructure()&&freeMeans&&g>0){double[] latentDifference=new double[factors.length];for(int j=0;j<factors.length;j++){int marker=position(observed,markers[j]);latentDifference[j]=(sample.means[marker]-samples.get(0).means[marker])/template.directed()[markers[j]][factors[j]];}for(int j=0;j<factors.length;j++){int factor=factors[j];double start=latentDifference[j];for(int k=0;k<factors.length;k++)start-=(warmA==null?a:warmA)[factor][factors[k]]*latentDifference[k];String name="Latent intercept: "+template.variables().get(factor);if(parameters.stream().anyMatch(p->p.name().equals(name)))throw new IllegalArgumentException("Template parameter name conflicts with generated latent intercept.");int marker=position(observed,markers[j]);parameters.add(new SemModel.Parameter(name,List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,factor,0)),start,Math.sqrt(sample.covariance[marker][marker])));}}
            var model=new SemModel.Model(template.variables(),observed,a,s,m,parameters);groups.add(new MultiGroupSem.Group(sample.name(),sample.observations,sample.covariance,sample.means,model,bindings));
        }
        return List.copyOf(groups);
    }
    private static int position(int[] values,int value){for(int i=0;i<values.length;i++)if(values[i]==value)return i;return -1;}
    private static void validate(SemModel.Prepared prepared,List<Sample> samples,CovarianceSem.Options options){
        if(samples.size()<2)throw new IllegalArgumentException("Measurement invariance needs at least two groups.");var model=prepared.model();int[] observed=model.observed(),factors=prepared.factors();Set<Integer> factorSet=new HashSet<>();for(int factor:factors)if(!factorSet.add(factor)||position(observed,factor)>=0)throw new IllegalArgumentException("Invariance factors must be unique unobserved variables.");if(factors.length<1||observed.length+factors.length!=model.variables().size())throw new IllegalArgumentException("Automatic invariance requires a reflective observed/factor template.");Set<Integer> freeIntercepts=new HashSet<>();for(var parameter:model.parameters()){if(parameter.locations().size()!=1)throw new IllegalArgumentException("Automatic invariance requires single-location template parameters; use explicit grouped RAM bindings for coupled constraints.");var location=parameter.locations().get(0);if(location.kind()==SemModel.Kind.INTERCEPT){if(position(observed,location.row())<0)throw new IllegalArgumentException("Template latent intercepts must be fixed to zero before automatic invariance.");freeIntercepts.add(location.row());}if(location.kind()==SemModel.Kind.DIRECTED&&position(observed,location.column())>=0)throw new IllegalArgumentException("Automatic invariance does not cover directed observed-variable parents.");}for(int column:observed)for(double[] row:model.directed())if(row[column]!=0)throw new IllegalArgumentException("Automatic invariance does not cover fixed directed observed-variable parents.");for(int factor:factors)if(model.intercepts()[factor]!=0)throw new IllegalArgumentException("Template latent intercepts must start fixed at zero.");if(options.meanStructure())for(int row:observed)if(!freeIntercepts.contains(row))throw new IllegalArgumentException("Automatic mean invariance needs a free intercept for every observed variable in the template.");for(var sample:samples)if(sample.covariance.length!=observed.length||sample.means.length!=observed.length)throw new IllegalArgumentException("Invariance samples must match the template observed order.");markers(model,factors,observed);
    }
    private static int[] markers(SemModel.Model model,int[] factors,int[] observed){int[] result=new int[factors.length];Arrays.fill(result,-1);double[][] a=model.directed();Set<String> free=new HashSet<>();for(var p:model.parameters())for(var l:p.locations())if(l.kind()==SemModel.Kind.DIRECTED)free.add(l.row()+":"+l.column());for(int j=0;j<factors.length;j++)for(int row:observed)if(a[row][factors[j]]!=0&&!free.contains(row+":"+factors[j])){boolean unique=true;for(int k=0;k<factors.length;k++)if(k!=j&&(a[row][factors[k]]!=0||free.contains(row+":"+factors[k])))unique=false;if(unique){result[j]=row;break;}}if(Arrays.stream(result).anyMatch(i->i<0))throw new IllegalArgumentException("Each invariance factor needs a distinct fixed, nonzero marker loading.");return result;}
}
